INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Switch auf Schicht 3 genauso schnell wie auf Schicht 2?', 2, '[{"text": "Nein", "correct": true, "because": "Schicht 3 benötigt Routing, was mehr Verarbeitung erfordert"}, {"text": "Ja", "correct": false, "because": "Schicht 2 ist simpler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutze ich für sichere Remote-Verbindungen?', 3, '[{"text": "SSH", "correct": true, "because": "Bietet verschlüsselte Verbindungen"}, {"text": "Telnet", "correct": false, "because": "Unsicher, unverschlüsselt"}, {"text": "FTP", "correct": false, "because": "Nur für Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen ein System vor Datenverlust?', 5, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Ermöglicht Wiederherstellung"}, {"text": "RAID", "correct": true, "because": "Schützt vor Festplattenausfall"}, {"text": "Hohe CPU-Leistung", "correct": false, "because": "Irrelevant für Datenverlust"}, {"text": "Schnelles Netzwerk", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) RAM ist flüchtig. b) SSDs sind langsamer als HDDs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSDs sind schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Servers für eine Datenbank?', 4, '[{"text": "RAM-Kapazität", "correct": false, "because": "Entscheidend für Performance"}, {"text": "Festplattengeschwindigkeit", "correct": false, "because": "Wichtig für Zugriffe"}, {"text": "Gehäusefarbe", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine CPU immer mit maximaler Taktfrequenz läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Takt variiert je nach Last"}, {"text": "Ja", "correct": false, "because": "Energiesparmodi senken Takt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für Netzwerküberwachung?', 3, '[{"text": "Wireshark", "correct": true, "because": "Analysiert Pakete detailliert"}, {"text": "Notepad", "correct": false, "because": "Nur ein Editor"}, {"text": "Task-Manager", "correct": false, "because": "Nur Systemressourcen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für einen Gaming-PC entscheidend?', 5, '[{"text": "Grafikkarte", "correct": true, "because": "Verarbeitet visuelle Daten"}, {"text": "CPU", "correct": true, "because": "Berechnet Spielphysik"}, {"text": "Bluetooth", "correct": false, "because": "Nur für Peripherie"}, {"text": "Lautsprecher", "correct": false, "because": "Nur Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) VLANs trennen Netzwerke logisch. b) Sie erhöhen die Bandbreite. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bandbreite bleibt gleich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Virtualisierung?', 4, '[{"text": "Hypervisor", "correct": false, "because": "Kern der Virtualisierung"}, {"text": "Ausreichend RAM", "correct": false, "because": "Wichtig für VMs"}, {"text": "Dedizierte GPU", "correct": true, "because": "Nur bei Grafikanwendungen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist IPv6 zwingend für lokale Netze?', 2, '[{"text": "Nein", "correct": true, "because": "IPv4 funktioniert lokal"}, {"text": "Ja", "correct": false, "because": "IPv6 ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sichern eine Software-Installation?', 4, '[{"text": "Verifizierung der Quelle", "correct": true, "because": "Schützt vor Malware"}, {"text": "Schnelle Internetverbindung", "correct": false, "because": "Nur für Download relevant"}, {"text": "Hohe Bildschirmauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein NAS nur für Backups ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Dateifreigabe"}, {"text": "Ja", "correct": false, "because": "NAS ist vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Routers?', 3, '[{"text": "Sicherheitsfeatures", "correct": true, "because": "Schützt Netzwerk"}, {"text": "Design", "correct": false, "because": "Ästhetik sekundär"}, {"text": "Preis", "correct": false, "because": "Funktion zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Proxy verbirgt die IP. b) Er beschleunigt immer das Netzwerk.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Caching ist nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Firewall?', 5, '[{"text": "Blockiert unerlaubten Zugriff", "correct": true, "because": "Filtert Datenverkehr"}, {"text": "Protokollierung", "correct": true, "because": "Erkennt Angriffe"}, {"text": "Erhöht CPU-Leistung", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Verbessert Bildqualität", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Motherboard unwichtig?', 3, '[{"text": "Chipsatz", "correct": false, "because": "Bestimmt Kompatibilität"}, {"text": "PCIe-Slots", "correct": false, "because": "Wichtig für Erweiterungen"}, {"text": "RGB-Beleuchtung", "correct": true, "because": "Nur ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Läuft DNS nur auf Schicht 7?', 3, '[{"text": "Ja", "correct": true, "because": "Anwendungsschicht-Protokoll"}, {"text": "Nein", "correct": false, "because": "DNS ist Schicht 7"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein BIOS-Update immer nötig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Problemen oder neuen CPUs"}, {"text": "Ja", "correct": false, "because": "System kann ohne stabil laufen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kabel wähle ich für 10 Gbit/s?', 4, '[{"text": "Cat6a", "correct": true, "because": "Unterstützt 10 Gbit/s"}, {"text": "Cat5", "correct": false, "because": "Nur bis 1 Gbit/s"}, {"text": "HDMI", "correct": false, "because": "Nur für Video"}]');
